    <table class="rep-tbl"><thead><tr><th>Sn.</th><th>Section</th><th class="r">Expected</th><th class="r">Collected</th><th class="r">Pending</th><th class="r">% Realised</th></tr></thead><tbody>${sectionRows}</tbody></table>
